import{_ as t,o as r,c as a,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Closer than you think- Cephs journey to nearest neighbor search","description":"","frontmatter":{"title":"Closer than you think- Cephs journey to nearest neighbor search","date":"2026-04-21T00:00:00.000Z","updated":"2026-04-21T00:00:00.000Z","tags":["Ceph","vector search","object storage","RGW","nearest neighbor search"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2026/Closer_than_you_think_-_Ceph_s_journey_to_nearest_neighbor_search.md","filePath":"posts/2026/Closer_than_you_think_-_Ceph_s_journey_to_nearest_neighbor_search.md","lastUpdated":1780459816000}'),i={name:"posts/2026/Closer_than_you_think_-_Ceph_s_journey_to_nearest_neighbor_search.md"};function l(n,e,s,c,h,d){return r(),a("div",null,[...e[0]||(e[0]=[o('<h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>本次演讲由 IBM 架构师 Kyle Bader 主讲，介绍了 Ceph 在 object storage 中引入 nearest neighbor search（近邻搜索）能力的工作进展。核心目标是让 Ceph RGW 兼容 Amazon S3 Vectors API，使用户无需额外部署独立的向量数据库系统，即可在 Ceph 集群中存储和检索 vector embedings。</p><h2 id="背景-什么是-vector-search" tabindex="-1">背景：什么是 Vector Search <a class="header-anchor" href="#背景-什么是-vector-search" aria-label="Permalink to &quot;背景：什么是 Vector Search&quot;">​</a></h2><p>演讲者以 Google Images 为例说明 vector search 的日常应用——用户输入关键词并附加颜色、尺寸等过滤条件，系统返回相似图片，这本质上是一种 hybrid approximate nearest neighbor search。</p><p>另一个典型场景是 LM 中的 <strong>Retrieval Augmented Generation（RAG）</strong>：在用户输入 prompt 后，系统通过 vector search 检索相关上下文并注入 prompt，以增强模型推理质量。</p><p><strong>Vector 的基本概念：</strong></p><ul><li>Vector 是多维空间中的点，每个维度代表某种特征属性（如身高、体重、眼睛颜色等）</li><li>常见维度数量可达 1024 维（float32 类型）</li><li>Vector 通常由 embedding 模型生成，例如 OpenAI 文本模型或医学影像特征提取模型</li><li>Approximate nearest neighbor search 即在向量空间中找到与查询向量最相似的 top-K 结果</li></ul><h2 id="amazon-s3-vectors-api" tabindex="-1">Amazon S3 Vectors API <a class="header-anchor" href="#amazon-s3-vectors-api" aria-label="Permalink to &quot;Amazon S3 Vectors API&quot;">​</a></h2><p>2025 年 12 月，AWS 发布了 S3 Vectors，对 S3 进行了扩展：</p><ul><li>新增 <strong>vector bucket</strong> 类型（区别于普通 bucket）</li><li>在 vector bucket 内可创建多个 <strong>index</strong>（子容器）</li><li>支持批量写入 vectors 到指定 index</li><li>支持 vector query，返回 top-K 相似结果</li><li>底层存储结构包含 vector 数据、自动构建的索引文件及版本指针</li></ul><p>这一设计的优势在于：unstructured data 与对应的 embedings 可以存储在同一系统中，无需额外维护独立的向量数据库。</p><h2 id="ceph-实现目标" tabindex="-1">Ceph 实现目标 <a class="header-anchor" href="#ceph-实现目标" aria-label="Permalink to &quot;Ceph 实现目标&quot;">​</a></h2><p>在 Ceph 中实现 S3 Vectors 兼容能力的核心目标：</p><ol><li><strong>低成本存储</strong>：无需额外部署 PGVector、Milvus、OpenSearch 等独立系统，利用 Ceph 现有的 replication、erasure coding、high availability 能力</li><li><strong>低空间放大率</strong>：index 数据与原始 embedding 数据的空间比不超过 3:1，因此选用 <strong>IVFPQ</strong>（Inverted File Index + Product Quantization）索引格式</li><li><strong>零额外基础设施</strong>：作为 RGW 的内置能力，不需要单独运维</li><li><strong>低延迟目标</strong>：sub-millisecond 级别的查询响应</li></ol><h2 id="设计参数" tabindex="-1">设计参数 <a class="header-anchor" href="#设计参数" aria-label="Permalink to &quot;设计参数&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>限制</th></tr></thead><tbody><tr><td>每个 vector bucket最大 index 数</td><td>10,000</td></tr><tr><td>单个 index 最大 embedding 数量</td><td>十亿级别</td></tr><tr><td>Vector 类型</td><td>Dense，float32</td></tr><tr><td>最大 top-K 返回数</td><td>30</td></tr><tr><td>批量写入限制</td><td>500 vectors或 20MB，取较小值</td></tr></tbody></table><h2 id="技术选型-向量库评估" tabindex="-1">技术选型：向量库评估 <a class="header-anchor" href="#技术选型-向量库评估" aria-label="Permalink to &quot;技术选型：向量库评估&quot;">​</a></h2><p>团队评估了三个主要的 approximate nearest neighbor 库：</p><p><strong>1. FAISS（Facebook AI Similarity Search）</strong></p><ul><li>最成熟、知名度最高</li><li>缺点：设计上要求将整个 index 加载到内存，在多租户 RGW 场景下内存开销不可接受，被排除</li></ul><p><strong>2. DiskANN</strong></p><ul><li>支持 cosine 和 L2（Euclidean）距离度量</li><li>C++ 实现，接口友好</li><li>缺点：仅提供索引构建能力，hybrid query（含 metadata 过滤）需要自行实现，工作量过大</li></ul><p><strong>3. LanceDB（最终选择）</strong></p><ul><li>同时支持 cosine 和 Euclidean 距离</li><li>使用 IVFPQ 索引，磁盘效率高</li><li>内置 hybrid search 能力，无需自行实现查询层</li><li>使用 Rust 编写，通过 Rust FFI（Foreign Function Interface）提供 C bindings，可被 C++ 的 RGW 调用</li><li>支持 merge-insert（upsert 语义），写入逻辑简洁</li><li>未来可通过 NVIDIA CUVS 库实现 GPU 加速索引构建</li></ul><h2 id="架构实现" tabindex="-1">架构实现 <a class="header-anchor" href="#架构实现" aria-label="Permalink to &quot;架构实现&quot;">​</a></h2><p>整体实现分为以下几个层次：</p><ol><li><strong>RGW 前端扩展</strong>：新增 S3 Vectors 相关的 API actions、请求解析、条件判断，并与现有 access control 机制集成</li><li><strong>请求处理层</strong>：policy 执行、rate limiting、请求路由</li><li><strong>向量库集成</strong>：LanceDB 作为嵌入式库加载到 RGW 进程中，负责序列化、索引构建和查询</li><li><strong>存储抽象层（zipper）</strong>：通过 RGW 的 zipper 存储抽象层对接 RADOS 后端，同时支持 standalone 文件系统模式；使用 RADOS 时自动获得 replication 和 erasure coding 保护</li></ol><h2 id="metadata-过滤方案" tabindex="-1">Metadata 过滤方案 <a class="header-anchor" href="#metadata-过滤方案" aria-label="Permalink to &quot;Metadata 过滤方案&quot;">​</a></h2><p>S3 Vectors API 支持在 query 时附带 metadata 过滤条件（每个 vector 最多 10 个 filterable key）。由于 filterable key 不固定，动态创建列会导致列数无界，团队最终采用 <strong>post-filtering</strong> 方案：</p><ul><li>查询时将 top-K 扩大若干倍，获取更多候选结果</li><li>在结果集上进行 metadata 过滤，返回符合条件的 top-K</li></ul><p>此外，团队还计划提供扩展能力：在 create index 时可预先声明 scalar schema，若提供了 schema，则为 filterable metadata 创建独立列，从而支持更高效的预过滤查询，同时保持与标准 S3 Vectors SDK 和 AWS CLI 的完全兼容。</p><h2 id="与-opensearch-的定位对比" tabindex="-1">与 OpenSearch 的定位对比 <a class="header-anchor" href="#与-opensearch-的定位对比" aria-label="Permalink to &quot;与 OpenSearch 的定位对比&quot;">​</a></h2><p>演讲者明确指出两者是互补关系，而非替代：</p><table tabindex="0"><thead><tr><th>场景</th><th>推荐方案</th></tr></thead><tbody><tr><td>大规模 embedding 存储 + 偶发查询 + 亚秒级响应可接受</td><td>S3 Vectors（Ceph 实现）</td></tr><tr><td>超低延迟（单位毫秒）+ 全文搜索 + 复杂 query DSL</td><td>OpenSearch</td></tr></tbody></table><h2 id="当前进展与-demo" tabindex="-1">当前进展与 Demo <a class="header-anchor" href="#当前进展与-demo" aria-label="Permalink to &quot;当前进展与 Demo&quot;">​</a></h2><p>演讲现场展示了基于 Rook 部署的 Ceph 集群（minikube 环境）的功能 Demo，通过 AWS CLI 完整演示了以下操作流程：</p><ol><li>创建 vector bucket（<code>movies</code>）</li><li>创建 vector index，指定 float32 数据类型、距离度量和维度数</li><li>批量写入 vectors（Star Wars、Aliens、Blade Runner 等电影数据）</li><li>列出 index 中的 vectors</li><li>执行 get vectors 操作</li><li>执行 query vectors，返回 top-3 相似结果</li><li>依次删除 vectors、index、vector bucket</li></ol><p><strong>当前实现状态：</strong></p><ul><li>前端请求处理已完成</li><li>IAM policy actions 已添加到语法，enforcement 部分仍在实现中</li><li>认证（authentication）已就绪，基于 bucket/identity policy 的授权（authorization）仍在开发</li><li>存储抽象层的最终对接工作进行中</li><li>已提供开发版容器镜像供实验使用</li></ul><h2 id="配置与资源管理" tabindex="-1">配置与资源管理 <a class="header-anchor" href="#配置与资源管理" aria-label="Permalink to &quot;配置与资源管理&quot;">​</a></h2><ul><li>S3 Vectors 功能需在 RGW 配置中显式启用（类似 IAM、STS 的启用方式），默认不开启</li><li>建议为运行 S3 Vectors 的 RGW 配置更多 CPU 和内存</li><li>可将 S3 Vectors 部署在独立的 RGW 实例集合上，与常规 S3 流量隔离</li><li>索引更新为异步后台操作，不阻塞 put vector 写入路径；新写入的 vectors 在索引合并前通过 brute-force 方式参与查询</li></ul><h2 id="q-a-要点" tabindex="-1">Q&amp;A 要点 <a class="header-anchor" href="#q-a-要点" aria-label="Permalink to &quot;Q&amp;A 要点&quot;">​</a></h2><ul><li><strong>GPU 加速</strong>：当前索引构建基于 CPU（x86 SIMD 指令），未来可探索通过 CUVS 支持 CUDA GPU 加速，类似 RGW 的 GC/lifecycle 后台任务模式</li><li><strong>兼容性动机</strong>：Ceph object storage 的一贯目标是跟进 S3 新特性，保证用户可以将 AWS应用直接迁移到 Ceph</li><li><strong>数据持久性讨论</strong>：会后 Q&amp;A 中讨论了 Ceph 的 durability 与 availability 的区别，Ceph 在 CAP 定理中优先保证 consistency，被描述为&quot;悲观型&quot;集群（pessimistic），会积极触发数据修复</li></ul>',43)])])}const g=t(i,[["render",l]]);export{u as __pageData,g as default};
